using System;using System.Data;using System.Text;public partial class AdminUsers:System.Web.UI.Page{public string usersHtml="";protected void Page_Load(object sender,EventArgs e){if(Session["userType"]==null||Session["userType"].ToString()!="Admin"){Response.Redirect("Home.aspx");return;}string where="";if(Page.IsPostBack){string q=MyAdoHelper.FixText(Request.Form["searchUser"]);where=" WHERE UserName LIKE N'%"+q+"%'";}DataTable dt=MyAdoHelper.ExecuteDataTable("SELECT UserId,FirstName,LastName,UserName,NickName,UserType,Coins FROM Users"+where);StringBuilder s=new StringBuilder("<table class='dataTable'><tr><th>ID</th><th>שם</th><th>שם משתמש</th><th>כינוי</th><th>סוג</th><th>מטבעות</th></tr>");for(int i=0;i<dt.Rows.Count;i++)s.Append("<tr><td>"+dt.Rows[i]["UserId"]+"</td><td>"+dt.Rows[i]["FirstName"]+" "+dt.Rows[i]["LastName"]+"</td><td>"+dt.Rows[i]["UserName"]+"</td><td>"+dt.Rows[i]["NickName"]+"</td><td>"+dt.Rows[i]["UserType"]+"</td><td>"+dt.Rows[i]["Coins"]+"</td></tr>");s.Append("</table>");usersHtml=s.ToString();}}